<script setup lang="ts">
import { products } from '~/shared/products'
const props = defineProps<{ kind: 'contact' | 'quote' }>()
const route = useRoute(); const lang = useState<'en'|'th'>('language')
const form = reactive({ kind: props.kind, name:'', email:'', phone:'', model: typeof route.query.model === 'string' ? route.query.model : '', message:'' })
const busy=ref(false), done=ref(false), error=ref('')
async function submit() { busy.value=true; error.value=''; try { await $fetch('/api/inquiries', {method:'POST',body:form}); done.value=true } catch { error.value=lang.value === 'th' ? 'ไม่สามารถส่งข้อมูลได้ กรุณาลองอีกครั้ง' : 'Unable to send your request. Please try again.' } finally {busy.value=false} }
</script>
<template><div><p v-if="done" class="success">{{ lang === 'th' ? 'ขอบคุณสำหรับข้อความ ทีมงานจะติดต่อกลับโดยเร็ว' : 'Thank you. Our team will be in touch.' }}</p><form v-else class="form" @submit.prevent="submit"><label>{{ lang === 'th' ? 'ชื่อ' : 'Name' }} *<input v-model="form.name" required maxlength="120" autocomplete="name"></label><label>{{ lang === 'th' ? 'อีเมล' : 'Email' }} *<input v-model="form.email" required type="email" maxlength="254" autocomplete="email"></label><label>{{ lang === 'th' ? 'เบอร์โทรศัพท์' : 'Phone' }}<input v-model="form.phone" maxlength="50" autocomplete="tel"></label><label v-if="kind === 'quote'">{{ lang === 'th' ? 'เลือกรุ่น' : 'Select a model' }} *<select v-model="form.model" required><option value="" disabled>{{ lang === 'th' ? 'เลือกรุ่นที่สนใจ' : 'Choose a model' }}</option><option v-for="p in products" :key="p.slug" :value="p.slug">{{ p.name }}</option></select></label><label>{{ lang === 'th' ? 'ข้อความ' : 'Message' }}{{ kind === 'contact' ? ' *' : '' }}<textarea v-model="form.message" :required="kind === 'contact'" maxlength="4000" rows="5"></textarea></label><p v-if="error" class="error">{{ error }}</p><button class="button dark" :disabled="busy">{{ busy ? '...' : (lang === 'th' ? 'ส่งข้อความ' : 'SEND MESSAGE') }} ↗</button></form></div></template>
